// Accounts whose weights drifted outside their no-trade band this hour.
const rows = $input.all().map((i) => i.json).filter((r) => r.account_id);
return [{
  json: {
    as_of: new Date().toISOString(),
    reason: 'drift',
    accounts: rows.map((r) => ({ account_id: r.account_id, max_abs_drift: Number(r.max_abs_drift), drifted: r.drifted ?? [] })),
  },
}];

// Rebalance proposals with deterministic ids per hour bucket (a retried run
// in the same hour cannot double-trade), shuffled for fair dispatch.
const hour = new Date(Math.floor(Date.now() / 3_600_000) * 3_600_000).toISOString();
const raw = Array.isArray($input.first().json.proposals) ? $input.first().json.proposals : [];
const props = raw
  .map((p) => ({ ...p, side: String(p?.side ?? '').toUpperCase(), qty: Number(p?.qty) }))
  .filter((p) => p.account_id && p.strategy_id && p.symbol && p.venue && (p.side === 'BUY' || p.side === 'SELL') && p.qty > 0)
  .map((p) => ({
    proposal_id: `rebal:${hour}:${p.account_id}:${p.strategy_id}:${p.venue}:${p.symbol}:${p.side}`,
    cycle_id: null,
    account_id: p.account_id,
    strategy_id: p.strategy_id,
    symbol: p.symbol,
    venue: p.venue,
    side: p.side,
    qty: p.qty,
    order_type: p.order_type ?? 'LIMIT',
    limit_px: p.limit_px ?? null,
    urgency: p.urgency ?? 'low',
    pair_id: p.pair_id ?? null,
    source: 'rebalance',
  }));
for (let i = props.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [props[i], props[j]] = [props[j], props[i]];
}
return props.map((p) => ({ json: p }));

// Bounded autonomy for the meta-learner: each strategy weight may move at
// most 5 percentage points per day and one-way turnover may not exceed 15%.
// Anything outside the envelope is staged for a human.
const MAX_STEP = 0.05;
const MAX_TURNOVER = 0.15;
const r = $input.first().json;
const prop = r.proposed_weights ?? {};
const cur = r.current_weights ?? {};
const keys = [...new Set([...Object.keys(prop), ...Object.keys(cur)])].sort();
const deltas = keys.map((k) => {
  const from = Number(cur[k] ?? 0);
  const to = Number(prop[k] ?? 0);
  return { strategy: k, from, to, delta: to - from };
});
const sum = Object.values(prop).reduce((a, b) => a + Number(b), 0);
const turnover = deltas.reduce((a, d) => a + Math.abs(d.delta), 0) / 2;
const violations = [];
if (!Object.keys(prop).length) violations.push('empty_proposal');
if (Math.abs(sum - 1) > 1e-6) violations.push(`weights_sum_${sum.toFixed(6)}`);
if (Object.values(prop).some((w) => !(Number(w) >= 0))) violations.push('negative_or_invalid_weight');
for (const d of deltas) if (Math.abs(d.delta) > MAX_STEP + 1e-12) violations.push(`step_${d.strategy}_${d.delta.toFixed(4)}`);
if (turnover > MAX_TURNOVER + 1e-12) violations.push(`turnover_${turnover.toFixed(4)}`);
return [{
  json: {
    proposed_weights: prop, current_weights: cur, deltas, turnover,
    within_bounds: violations.length === 0, violations, diagnostics: r.diagnostics ?? null,
  },
}];

// --- shared: Claude Messages API helpers (inlined at build time) -----------
// One model for every LLM route; effort is tuned per route. Structured outputs
// (output_config.format) guarantee schema-valid JSON. Server-side fallbacks
// re-run a declined request on Anthropic's recommended fallback model.
// Any refusal, truncation, HTTP error or bad JSON returns ok=false so the
// caller takes its deterministic path: no LLM sits on a path that moves money.
const CLAUDE_MODEL = 'claude-opus-5-5';
function claudeRequest({ system, user, schema, effort = 'low', maxTokens = 8000 }) {
  return {
    model: CLAUDE_MODEL,
    max_tokens: maxTokens,
    fallbacks: 'default',
    system,
    output_config: { effort, format: { type: 'json_schema', schema } },
    messages: [{ role: 'user', content: typeof user === 'string' ? user : JSON.stringify(user) }],
  };
}
function parseClaude(item) {
  if (!item) return { ok: false, reason: 'no_response' };
  if (item.error) return { ok: false, reason: 'http_error', detail: String(item.error.message ?? item.error).slice(0, 300) };
  const status = item.statusCode;
  const msg = item.body ?? item;
  if (status && (status < 200 || status >= 300)) return { ok: false, reason: `http_${status}`, detail: msg?.error?.type ?? null };
  if (msg?.stop_reason === 'refusal') return { ok: false, reason: 'refusal', detail: msg.stop_details?.category ?? null };
  if (msg?.stop_reason === 'max_tokens') return { ok: false, reason: 'max_tokens' };
  const text = (msg?.content ?? []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  try {
    return { ok: true, data: JSON.parse(text), model: msg.model ?? CLAUDE_MODEL, usage: msg.usage ?? null };
  } catch {
    return { ok: false, reason: 'invalid_json' };
  }
}
// --- end shared --------------------------------------------------------------

// Portfolio agent review. It can recommend human review (adding caution)
// but cannot approve anything or widen the envelope.
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['summary', 'concerns', 'recommend_human_review'],
  properties: {
    summary: { type: 'string' },
    concerns: { type: 'array', items: { type: 'string' } },
    recommend_human_review: { type: 'boolean' },
  },
};
const system = [
  'You review a proposed daily change to strategy capital weights for a systematic crypto portfolio.',
  'The change was produced by an online meta-learner and already passed or failed a bounded-change policy.',
  'Explain the change in plain language for the audit log (at most four sentences), list concrete concerns',
  '(concentration, regime fit, crowding, data quality, correlation), and set recommend_human_review to true',
  'if anything warrants a human look. You cannot approve changes. Use only the numbers provided.',
].join(' ');
const b = $input.first().json;
return [{ json: { anthropic_request: claudeRequest({ system, user: b, schema, effort: 'medium', maxTokens: 6000 }) } }];

// --- shared: Claude Messages API helpers (inlined at build time) -----------
// One model for every LLM route; effort is tuned per route. Structured outputs
// (output_config.format) guarantee schema-valid JSON. Server-side fallbacks
