  } catch {
    return { ok: false, reason: 'invalid_json' };
  }
}
// --- end shared --------------------------------------------------------------

// apply: inside the envelope and the agent saw no reason for review.
// stage: everything else. The agent can add caution, never remove it; if the
// review is unavailable the bounded-change policy alone decides.
const b = $('Bounded-change policy').first().json;
const t = parseClaude($input.first().json);
const review = t.ok ? t.data : null;
const auto = b.within_bounds === true && review?.recommend_human_review !== true;
return [{
  json: {
    ...b,
    review,
    review_error: t.ok ? null : t.reason,
    path: auto ? 'apply' : 'stage',
    rationale: review?.summary ?? `bounded-change policy: ${b.within_bounds ? 'within envelope' : b.violations.join(', ')}`,
  },
}];

// Approval request with one-time links to this execution's Wait node.
// The token is single-use and expires with the staged allocation (4 h).
// The ops chat must be restricted to authorised risk approvers.
const staged = $('Stage allocation').first().json.r;
const d = $('Decide path').first().json;
const token = $('Approval token').first().json.token;
const link = (decision) => `${$execution.resumeUrl}?decision=${decision}&v=${staged.version_id}&token=${token}&approver=YOUR_ID`;
const moves = d.deltas
  .filter((x) => Math.abs(x.delta) > 1e-9)
  .map((x) => `${x.strategy}: ${(x.from * 100).toFixed(1)}% -> ${(x.to * 100).toFixed(1)}%`);
const why = d.violations.length ? d.violations.join(', ') : 'portfolio agent requested human review';
return [{
  json: {
    version_id: staged.version_id,
    text: [
      `[APPROVAL] Strategy allocation v${staged.version_id} (expires in 4 h)`,
      ...moves,
      `Why staged: ${why}`,
      `Agent notes: ${d.review?.summary ?? 'n/a'}`,
      `Approve: ${link('approve')}`,
      `Reject: ${link('reject')}`,
    ].join('\n'),
  },
}];

// Reads the approver's click (query string) or the Wait timeout. A timeout
// is recorded as a rejection; the current allocation stays in force.
const q = $input.first().json.query ?? {};
const msg = $('Build approval message').first().json;
const timedOut = !q.decision;
return [{
  json: {
    version_id: msg.version_id,
    token: timedOut ? $('Approval token').first().json.token : String(q.token ?? ''),
    decision: timedOut ? 'timeout' : String(q.decision).toLowerCase(),
    approver: timedOut ? 'timeout' : String(q.approver ?? 'unknown').slice(0, 80),
    timed_out: timedOut,
  },
}];
